.mta-count-ledger-glow{position:absolute;left:0;right:0;top:-60%;height:150%;pointer-events:none;background:radial-gradient(52% 42% at 80% 46%,rgba(255,196,107,.20),transparent 70%)}
.mta-count-ledger-top{position:relative;display:flex;align-items:center;gap:10px}
.mta-count-ledger-eyebrow{font-size:10px;letter-spacing:.18em;text-transform:uppercase;color:#8d8471}
