.mta-count-ledger-value{position:relative;display:flex;align-items:baseline;gap:4px;margin:11px 0 3px;animation:mta-count-ledger-rise .72s cubic-bezier(.18,.9,.28,1) both}
.mta-count-ledger-cur{font-size:17px;color:#ffc46b;align-self:flex-start;margin-top:2px}
.mta-count-ledger-num{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:34px;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums;color:#fff4e2}
