var nums = Array.prototype.slice.call(root.querySelectorAll('[data-to]'));
var bars = Array.prototype.slice.call(root.querySelectorAll('.mta-count-ledger-bar i'));
var btn = root.querySelector('.mta-count-ledger-replay');
var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var raf = 0;

function fmt(v, dec) {
  var parts = v.toFixed(dec).split('.');
  parts[0] = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return parts.join('.');
}
function paint(k) {
  for (var i = 0; i < nums.length; i++) {
    var el = nums[i];
    var to = parseFloat(el.getAttribute('data-to')) || 0;
    var dec = parseInt(el.getAttribute('data-dec') || '0', 10);
    el.textContent = fmt(to * k, dec);
  }
}
function fill(on) {
  for (var i = 0; i < bars.length; i++) {
    bars[i].style.width = on ? bars[i].getAttribute('data-w') + '%' : '0%';
  }
}
function run() {
  if (raf) { cancelAnimationFrame(raf); raf = 0; }
  if (reduced) { paint(1); fill(true); return; }
  paint(0);
  fill(false);
  var start = 0;
  var dur = 1400;
  function tick(now) {
    if (!root.isConnected) { raf = 0; return; }
    if (!start) { start = now; fill(true); }
    var p = Math.min(1, (now - start) / dur);
    paint(1 - Math.pow(1 - p, 4));
    raf = p < 1 ? requestAnimationFrame(tick) : 0;
  }
  raf = requestAnimationFrame(tick);
}
if (btn) {
  btn.addEventListener('click', function () {
    var v = root.querySelector('.mta-count-ledger-value');
    if (v && !reduced) { v.style.animation = 'none'; void v.offsetWidth; v.style.animation = ''; }
    run();
  });
}
run();

