.mta-stat-cascade{box-sizing:border-box;width:100%;max-width:340px;padding:13px;border-radius:16px;background:linear-gradient(180deg,#151223 0%,#0a0910 100%);border:1px solid rgba(150,130,255,.18);color:#e8e6f6;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
