.mta-stat-cascade-title{font-size:10px;letter-spacing:.16em;text-transform:uppercase;color:#8f89b5}
.mta-stat-cascade-live{display:inline-flex;align-items:center;gap:5px;font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#8ce0c0}
.mta-stat-cascade-live i{width:6px;height:6px;border-radius:50%;background:#8ce0c0;animation:mta-stat-cascade-blip 1.9s ease-in-out infinite}
.mta-stat-cascade-replay{margin-left:auto;padding:4px 9px;border-radius:7px;border:1px solid rgba(150,130,255,.28);background:rgba(150,130,255,.1);color:#c3b4ff;font:inherit;font-size:10px;cursor:pointer;transition:background .18s ease,color .18s ease,transform .12s ease}
.mta-stat-cascade-replay:hover{background:rgba(150,130,255,.22);color:#efe9ff}
.mta-stat-cascade-replay:active{transform:translateY(1px)}
.mta-stat-cascade-replay:focus-visible{outline:2px solid #b39bff;outline-offset:2px}
.mta-stat-cascade-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.mta-stat-cascade-tile{position:relative;padding:10px 10px 11px;border-radius:12px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.06);overflow:hidden;animation:mta-stat-cascade-in .62s cubic-bezier(.2,.85,.3,1) both;animation-delay:calc(var(--mta-sc-i,0)*95ms);transition:border-color .2s ease,background .2s ease}
.mta-stat-cascade-tile:hover{background:rgba(255,255,255,.06);border-color:rgba(150,130,255,.34)}
.mta-stat-cascade-k{display:block;font-size:9px;letter-spacing:.13em;text-transform:uppercase;color:#7f79a6}
.mta-stat-cascade-v{display:block;margin:6px 0 9px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:19px;line-height:1;font-variant-numeric:tabular-nums;color:#f2effe}
.mta-stat-cascade-v em{font-style:normal;font-size:10px;color:#8f89b5;margin-left:2px}
.mta-stat-cascade-track{display:block;height:3px;border-radius:2px;background:rgba(255,255,255,.09);overflow:hidden}
.mta-stat-cascade-track i{display:block;height:100%;width:var(--mta-sc-f,50%);border-radius:2px;background:linear-gradient(90deg,#5b46e0,#b39bff);animation:mta-stat-cascade-fill .95s cubic-bezier(.16,.86,.36,1) both;animation-delay:calc(var(--mta-sc-i,0)*95ms + 170ms)}
.mta-stat-cascade-chip{position:absolute;top:9px;right:9px;padding:2px 5px;border-radius:5px;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9px;animation:mta-stat-cascade-pop .45s cubic-bezier(.2,1.4,.4,1) both;animation-delay:calc(var(--mta-sc-i,0)*95ms + 380ms)}
.mta-stat-cascade-good{color:#7ee0a8;background:rgba(126,224,168,.13)}
.mta-stat-cascade-bad{color:#ff9494;background:rgba(255,148,148,.13)}
@keyframes mta-stat-cascade-in{from{opacity:0;transform:translateY(14px) scale(.97);filter:blur(4px)}to{opacity:1;transform:none;filter:blur(0)}}
@keyframes mta-stat-cascade-fill{from{width:0}to{width:var(--mta-sc-f,50%)}}
@keyframes mta-stat-cascade-pop{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:none}}
@keyframes mta-stat-cascade-blip{0%,100%{opacity:.35;transform:scale(.8)}50%{opacity:1;transform:scale(1)}}
@media (prefers-reduced-motion: reduce){
.mta-stat-cascade-tile{animation:none}
.mta-stat-cascade-track i{animation:none}
.mta-stat-cascade-chip{animation:none}
.mta-stat-cascade-live i{animation:none}
}

js:
var tiles = Array.prototype.slice.call(root.querySelectorAll('.mta-stat-cascade-tile'));
var btn = root.querySelector('.mta-stat-cascade-replay');
var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
if (btn && reduced) { btn.disabled = true; }
if (btn && !reduced) {
  btn.addEventListener('click', function () {
    var parts = [];
    for (var i = 0; i < tiles.length; i++) {
      parts.push(tiles[i]);
      var bar = tiles[i].querySelector('.mta-stat-cascade-track i');
      var chip = tiles[i].querySelector('.mta-stat-cascade-chip');
      if (bar) parts.push(bar);
      if (chip) parts.push(chip);
    }
    for (var j = 0; j < parts.length; j++) parts[j].style.animation = 'none';
    void root.offsetWidth;
    for (var k = 0; k < parts.length; k++) parts[k].style.animation = '';
  });
}

