var line = root.querySelector('.mta-live-sparkline-line');
var area = root.querySelector('.mta-live-sparkline-area');
var shift = root.querySelector('.mta-live-sparkline-shift');
var dot = root.querySelector('.mta-live-sparkline-dot');
var out = root.querySelector('.mta-live-sparkline-val');
var peakOut = root.querySelector('.mta-live-sparkline-peak');
var btn = root.querySelector('.mta-live-sparkline-toggle');
if (!line || !area) return;

var N = 46, W = 320, H = 78, PAD = 9;
var step = W / (N - 2);
var lo = 400, hi = 2200;
var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var vals = [], cur = 1240, peak = 0;

function fmt(v) { return Math.round(v).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function walk(v) {
  var n = v + (Math.random() - 0.5) * 300 + (1320 - v) * 0.09;
  return Math.max(lo + 60, Math.min(hi - 60, n));
}
function y(v) { return H - PAD - (v - lo) / (hi - lo) * (H - PAD * 2); }
function draw() {
  var pts = [];
  for (var i = 0; i < N; i++) pts.push((i * step).toFixed(1) + ',' + y(vals[i]).toFixed(1));
  var s = pts.join(' ');
  line.setAttribute('points', s);
  area.setAttribute('points', '-2,' + H + ' ' + s + ' ' + ((N - 1) * step).toFixed(1) + ',' + H);
  var last = vals[N - 1];
  if (out) out.textContent = fmt(last);
  if (dot) dot.style.top = (y(last) / H * 100).toFixed(2) + '%';
  if (peakOut) peakOut.textContent = 'peak ' + fmt(peak);
}
function push() {
  cur = walk(cur);
  if (cur > peak) peak = cur;
  vals.push(cur);
  vals.shift();
  draw();
}
for (var i = 0; i < N; i++) { cur = walk(cur); if (cur > peak) peak = cur; vals.push(cur); }
draw();

var raf = 0, last = 0, acc = 0, tick = 700, paused = false;
function frame(now) {
  if (!root.isConnected) { raf = 0; return; }
  if (!last) last = now;
  var dt = Math.min(240, now - last);
  last = now;
  acc += dt;
  while (acc >= tick) { acc -= tick; push(); }
  if (shift) shift.setAttribute('transform', 'translate(' + (-(acc / tick) * step).toFixed(2) + ' 0)');
  raf = requestAnimationFrame(frame);
}
function start() { if (!raf && !paused && !reduced) { last = 0; raf = requestAnimationFrame(frame); } }
function stop() { if (raf) { cancelAnimationFrame(raf); raf = 0; } }
if (btn) {
  if (reduced) { btn.disabled = true; btn.textContent = 'Paused'; }
  btn.addEventListener('click', function () {
    paused = !paused;
    btn.setAttribute('aria-pressed', paused ? 'true' : 'false');
    btn.textContent = paused ? 'Resume' : 'Pause';
    if (paused) stop(); else start();
  });
}
start();

