.mta-ring-cluster{box-sizing:border-box;width:100%;max-width:340px;padding:14px;border-radius:16px;background:radial-gradient(120% 130% at 12% 0%,#1c1529 0%,#09080e 68%);border:1px solid rgba(255,255,255,.09);color:#eee9f7;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif}
