js:
var arcs = Array.prototype.slice.call(root.querySelectorAll('.mta-ring-cluster-arc'));
var outs = Array.prototype.slice.call(root.querySelectorAll('.mta-ring-cluster-pct'));
var btn = root.querySelector('.mta-ring-cluster-cycle');
var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
var targets = [], shown = [], circ = [], raf = 0;

for (var i = 0; i < arcs.length; i++) {
  var r = parseFloat(arcs[i].getAttribute('r')) || 1;
  var c = 2 * Math.PI * r;
  circ.push(c);
  arcs[i].style.strokeDasharray = c.toFixed(2);
  arcs[i].style.strokeDashoffset = c.toFixed(2);
  targets.push(parseFloat(arcs[i].getAttribute('data-v')) || 0);
  shown.push(0);
}
function label(k) {
  for (var i = 0; i < outs.length; i++) {
    outs[i].textContent = Math.round(shown[i] + (targets[i] - shown[i]) * k) + '%';
  }
}
function apply() {
  for (var i = 0; i < arcs.length; i++) {
    arcs[i].style.strokeDashoffset = (circ[i] * (1 - targets[i] / 100)).toFixed(2);
  }
  if (raf) { cancelAnimationFrame(raf); raf = 0; }
  if (reduced) { label(1); shown = targets.slice(); return; }
  var start = 0, dur = 1350;
  function tick(now) {
    if (!root.isConnected) { raf = 0; return; }
    if (!start) start = now;
    var p = Math.min(1, (now - start) / dur);
    label(1 - Math.pow(1 - p, 3));
    if (p < 1) { raf = requestAnimationFrame(tick); }
    else { raf = 0; shown = targets.slice(); }
  }
  raf = requestAnimationFrame(tick);
}
if (btn) {
  btn.addEventListener('click', function () {
    for (var i = 0; i < targets.length; i++) {
      targets[i] = Math.max(8, Math.min(99, Math.round(20 + Math.random() * 78)));
    }
    apply();
  });
}
requestAnimationFrame(function () { if (!root.isConnected) return; apply(); });

