js:
var body = root.querySelector('.mta-row-stagger-body');
var btns = Array.prototype.slice.call(root.querySelectorAll('.mta-row-stagger-sort'));
if (!body) return;
var rows = Array.prototype.slice.call(body.querySelectorAll('.mta-row-stagger-row'));
var key = 'value';
var dir = -1;

function render(replay) {
  var sorted = rows.slice().sort(function (a, b) {
    var d = key === 'name'
      ? a.getAttribute('data-name').localeCompare(b.getAttribute('data-name'))
      : parseFloat(a.getAttribute('data-value')) - parseFloat(b.getAttribute('data-value'));
    return d * dir;
  });
  sorted.forEach(function (row, i) {
    body.appendChild(row);
    row.style.setProperty('--mta-rs-i', String(i));
    var rank = row.querySelector('.mta-row-stagger-rank');
    if (rank) rank.textContent = String(i + 1);
    var fill = row.querySelector('.mta-row-stagger-fill');
    if (replay) { row.style.animation = 'none'; }
    if (fill) fill.style.width = '0%';
  });
  void body.offsetWidth;
  sorted.forEach(function (row) {
    if (replay) row.style.animation = '';
    var fill = row.querySelector('.mta-row-stagger-fill');
    if (fill) fill.style.width = fill.getAttribute('data-w') + '%';
  });
}
btns.forEach(function (btn) {
  btn.addEventListener('click', function () {
    var k = btn.getAttribute('data-key');
    if (k === key) { dir = -dir; } else { key = k; dir = k === 'name' ? 1 : -1; }
    btns.forEach(function (o) {
      var on = o.getAttribute('data-key') === key;
      o.setAttribute('aria-pressed', on ? 'true' : 'false');
      var base = o.getAttribute('data-key') === 'name' ? 'Region' : 'Sessions';
      o.textContent = on ? base + (dir > 0 ? ' ▲' : ' ▼') : base;
    });
    render(true);
  });
});
render(true);

