js:
var grid = root.querySelector('.mta-heat-pulse-grid');
var read = root.querySelector('.mta-heat-pulse-read');
var total = root.querySelector('.mta-heat-pulse-total');
if (!grid) return;
var cells = Array.prototype.slice.call(grid.querySelectorAll('.mta-heat-pulse-cell'));
var sum = 0;
for (var i = 0; i < cells.length; i++) sum += parseInt(cells[i].getAttribute('data-n'), 10) || 0;

function level(n) { return n === 0 ? 0 : n <= 2 ? 1 : n <= 5 ? 2 : n <= 9 ? 3 : 4; }
function say(cell) {
  if (!read) return;
  var n = parseInt(cell.getAttribute('data-n'), 10) || 0;
  read.textContent = cell.getAttribute('data-day') + ' · ' + n + (n === 1 ? ' deploy' : ' deploys');
}
grid.addEventListener('mouseover', function (e) {
  var c = e.target.closest ? e.target.closest('.mta-heat-pulse-cell') : null;
  if (c) say(c);
});
grid.addEventListener('focusin', function (e) {
  var c = e.target.closest ? e.target.closest('.mta-heat-pulse-cell') : null;
  if (c) say(c);
});
grid.addEventListener('mouseleave', function () { if (read) read.textContent = 'hover a day'; });
cells.forEach(function (c) {
  c.addEventListener('animationend', function () { c.classList.remove('is-hot'); });
});
var id = setInterval(function () {
  if (!root.isConnected) { clearInterval(id); return; }
  var c = cells[Math.floor(Math.random() * cells.length)];
  var was = parseInt(c.getAttribute('data-n'), 10) || 0;
  var now = Math.max(0, Math.min(14, was + Math.round((Math.random() - 0.35) * 7)));
  if (now === was) now = was + 1;
  sum += now - was;
  c.setAttribute('data-n', String(now));
  c.setAttribute('data-lvl', String(level(now)));
  c.setAttribute('aria-label', c.getAttribute('data-day') + ': ' + now + (now === 1 ? ' deploy' : ' deploys'));
  c.classList.remove('is-hot');
  void c.offsetWidth;
  c.classList.add('is-hot');
  if (total) {
    total.textContent = String(sum);
    total.classList.remove('is-bump');
    void total.offsetWidth;
    total.classList.add('is-bump');
  }
}, 1100);

