js:
var rows = Array.prototype.slice.call(root.querySelectorAll('.mta-diff-flash-row'));
var clock = root.querySelector('.mta-diff-flash-clock');
var btn = root.querySelector('.mta-diff-flash-freeze');
var frozen = false;

rows.forEach(function (row) {
  var px = row.querySelector('.mta-diff-flash-px');
  if (px) px.addEventListener('animationend', function () {
    row.classList.remove('is-up');
    row.classList.remove('is-down');
  });
});
function pad(v) { return (v < 10 ? '0' : '') + v; }
function stamp() {
  var d = new Date();
  return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
function tickRow(row) {
  var dec = parseInt(row.getAttribute('data-dec'), 10) || 2;
  var last = parseFloat(row.getAttribute('data-px'));
  var open = parseFloat(row.getAttribute('data-open'));
  var stepSize = Math.pow(10, -dec);
  var move = (Math.round(Math.random() * 7) + 1) * stepSize * (Math.random() > 0.5 ? 1 : -1);
  var next = last + move;
  if (next <= 0) next = last + Math.abs(move);
  row.setAttribute('data-px', next.toFixed(dec));
  var px = row.querySelector('.mta-diff-flash-px');
  var chg = row.querySelector('.mta-diff-flash-chg');
  if (px) px.textContent = next.toFixed(dec);
  if (chg) {
    var pct = (next - open) / open * 100;
    chg.textContent = (pct >= 0 ? '+' : '−') + Math.abs(pct).toFixed(2) + '%';
    chg.className = 'mta-diff-flash-chg ' + (pct >= 0 ? 'mta-diff-flash-pos' : 'mta-diff-flash-neg');
  }
  row.classList.remove('is-up');
  row.classList.remove('is-down');
  void row.offsetWidth;
  row.classList.add(next > last ? 'is-up' : 'is-down');
}
if (btn) {
  btn.addEventListener('click', function () {
    frozen = !frozen;
    btn.setAttribute('aria-pressed', frozen ? 'true' : 'false');
    btn.textContent = frozen ? 'Resume' : 'Freeze';
  });
}
if (clock) clock.textContent = stamp();
var id = setInterval(function () {
  if (!root.isConnected) { clearInterval(id); return; }
  if (frozen) return;
  var picks = 1 + Math.floor(Math.random() * 2);
  var pool = rows.slice();
  while (picks-- > 0 && pool.length) {
    tickRow(pool.splice(Math.floor(Math.random() * pool.length), 1)[0]);
  }
  if (clock) clock.textContent = stamp();
}, 1250);

