js:
var view = root.querySelector('.mta-stream-log-view');
var btn = root.querySelector('.mta-stream-log-btn');
var jump = root.querySelector('.mta-stream-log-jump');
var rate = root.querySelector('.mta-stream-log-rate');
var dot = root.querySelector('.mta-stream-log-dot');
if (!view) return;
var pool = [
  ['info', 'batch 4418 flushed · 1,024 rows'],
  ['info', 'checkpoint written to shard-02'],
  ['warn', 'retry 2/5 · upstream returned 429'],
  ['info', 'lease renewed for consumer-7'],
  ['err', 'dropped malformed envelope id=8f2c'],
  ['info', 'compaction finished in 412ms'],
  ['warn', 'lag 4.1s on partition 11'],
  ['info', 'ack window advanced to 91422'],
  ['info', 'gc pause 18ms · heap 61%']
];
var stick = true, paused = false, missed = 0, count = 4;

function pad(v) { return (v < 10 ? '0' : '') + v; }
function stamp() {
  var d = new Date();
  return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
}
function span(cls, text) {
  var el = document.createElement('span');
  el.className = cls;
  el.textContent = text;
  return el;
}
function add() {
  var item = pool[Math.floor(Math.random() * pool.length)];
  var row = document.createElement('div');
  row.className = 'mta-stream-log-line mta-stream-log-' + item[0];
  row.appendChild(span('mta-stream-log-t', stamp()));
  row.appendChild(span('mta-stream-log-lvl', item[0].toUpperCase()));
  row.appendChild(span('mta-stream-log-msg', item[1]));
  view.appendChild(row);
  while (view.children.length > 44) view.removeChild(view.firstChild);
  count++;
  if (rate) rate.textContent = count + ' lines';
  if (stick) {
    view.scrollTop = view.scrollHeight;
  } else if (jump) {
    missed++;
    jump.textContent = missed + ' new ↓';
    jump.classList.add('is-on');
  }
}
function follow() {
  stick = true;
  missed = 0;
  if (jump) jump.classList.remove('is-on');
  view.scrollTop = view.scrollHeight;
}
view.addEventListener('scroll', function () {
  var gap = view.scrollHeight - view.scrollTop - view.clientHeight;
  if (gap < 10) {
    stick = true;
    missed = 0;
    if (jump) jump.classList.remove('is-on');
  } else {
    stick = false;
  }
});
if (jump) jump.addEventListener('click', follow);
if (btn) {
  btn.addEventListener('click', function () {
    paused = !paused;
    btn.setAttribute('aria-pressed', paused ? 'true' : 'false');
    btn.textContent = paused ? 'Resume' : 'Pause';
    if (dot) dot.classList.toggle('is-off', paused);
  });
}
view.scrollTop = view.scrollHeight;
var id = setInterval(function () {
  if (!root.isConnected) { clearInterval(id); return; }
  if (paused) return;
  add();
}, 950);

