var digits = root.querySelector('.mta-odometer-roll-digits');
var out = root.querySelector('.mta-odometer-roll-sr');
var btn = root.querySelector('.mta-odometer-roll-btn');
var CELL = 36, SPIN = 10, cols = [], value = 4820697;

function fmt(n){ return n.toLocaleString('en-US'); }

function build(str){
  digits.textContent = '';
  cols = [];
  for (var i = 0; i < str.length; i++){
    var ch = str.charAt(i);
    if (ch === ','){
      var sep = document.createElement('span');
      sep.className = 'mta-odometer-roll-sep';
      sep.textContent = ',';
      digits.appendChild(sep);
      continue;
    }
    var col = document.createElement('span');
    col.className = 'mta-odometer-roll-col';
    var strip = document.createElement('span');
    strip.className = 'mta-odometer-roll-strip';
    for (var k = 0; k <= SPIN + 9; k++){
      var cell = document.createElement('span');
      cell.textContent = String(k % 10);
      strip.appendChild(cell);
    }
    col.appendChild(strip);
    digits.appendChild(col);
    cols.push({ strip: strip, d: parseInt(ch, 10) });
  }
}

function roll(){
  cols.forEach(function(c){
    c.strip.style.transition = 'none';
    c.strip.style.transitionDelay = '0ms';
    c.strip.style.transform = 'translateY(0px)';
  });
  void digits.offsetWidth;
  cols.forEach(function(c, i){
    c.strip.style.transition = '';
    c.strip.style.transitionDelay = (i * 55) + 'ms';
    c.strip.style.transform = 'translateY(-' + ((SPIN + c.d) * CELL) + 'px)';
  });
}

function show(n){
  build(fmt(n));
  out.textContent = '$' + fmt(n);
  roll();
}

show(value);

btn.addEventListener('click', function(){
  value += 1200 + Math.floor(Math.random() * 88000);
  show(value);
});

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  value += 400 + Math.floor(Math.random() * 9000);
  show(value);
}, 5200);

