var tiles = Array.prototype.slice.call(root.querySelectorAll('.mta-mount-wipe-tile'));
var btn = root.querySelector('.mta-mount-wipe-replay');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = 0;

function fmt(v, k){
  if (k === 'ms') return Math.round(v) + ' ms';
  if (k === 'pct2') return v.toFixed(2) + '%';
  if (k === 'pct1') return v.toFixed(1) + '%';
  return Math.round(v).toLocaleString('en-US');
}

function paint(t, v){ t.querySelector('.mta-mount-wipe-v').textContent = fmt(v, t.getAttribute('data-fmt')); }

function run(){
  if (raf) cancelAnimationFrame(raf);
  if (reduce){
    tiles.forEach(function(t){ paint(t, parseFloat(t.getAttribute('data-to'))); });
    return;
  }
  var t0 = 0;
  function step(ts){
    if (!root.isConnected) return;
    if (!t0) t0 = ts;
    var e = ts - t0, live = false;
    tiles.forEach(function(t, i){
      var p = Math.min(1, Math.max(0, (e - (i * 95 + 140)) / 900));
      if (p < 1) live = true;
      paint(t, parseFloat(t.getAttribute('data-to')) * (1 - Math.pow(1 - p, 3)));
    });
    raf = live ? requestAnimationFrame(step) : 0;
  }
  raf = requestAnimationFrame(step);
}

function play(){
  root.classList.remove('is-on');
  void root.offsetWidth;
  root.classList.add('is-on');
  run();
}

btn.addEventListener('click', play);
play();

