var wrap = root.querySelector('.mta-throughput-bars-bars');
var now = root.querySelector('.mta-throughput-bars-now b');
var peak = root.querySelector('.mta-throughput-bars-peak');
var peakLabel = root.querySelector('.mta-throughput-bars-peak em');
var tip = root.querySelector('.mta-throughput-bars-tip');
var toggle = root.querySelector('.mta-throughput-bars-toggle');
var N = 30, MAX = 120, vals = [], bars = [], paused = false, base = 48;

for (var i = 0; i < N; i++){
  base = Math.max(18, Math.min(104, base + (Math.random() - .5) * 22));
  vals.push(Math.round(base));
  var b = document.createElement('span');
  b.className = 'mta-throughput-bars-bar';
  b.setAttribute('data-i', String(i));
  b.appendChild(document.createElement('i'));
  wrap.appendChild(b);
  bars.push(b);
}

function paint(flash){
  var top = 0;
  vals.forEach(function(v){ if (v > top) top = v; });
  bars.forEach(function(b, i){
    var v = vals[i];
    b.querySelector('i').style.height = Math.max(4, (v / MAX) * 100) + '%';
    b.classList.toggle('is-hot', v > 92);
  });
  peak.style.top = (100 - (top / MAX) * 100) + '%';
  peakLabel.textContent = 'peak ' + top;
  now.textContent = vals[N - 1];
  if (flash){
    var last = bars[N - 1];
    last.classList.remove('is-new');
    void last.offsetWidth;
    last.classList.add('is-new');
  }
}

paint(false);

wrap.addEventListener('mousemove', function(e){
  var b = e.target.closest ? e.target.closest('.mta-throughput-bars-bar') : null;
  if (!b){ tip.classList.remove('is-on'); return; }
  var i = parseInt(b.getAttribute('data-i'), 10);
  tip.textContent = vals[i] + ' req/s';
  tip.style.left = (b.offsetLeft + b.offsetWidth / 2) + 'px';
  tip.classList.add('is-on');
});
wrap.addEventListener('mouseleave', function(){ tip.classList.remove('is-on'); });

toggle.addEventListener('click', function(){
  paused = !paused;
  toggle.setAttribute('aria-pressed', paused ? 'true' : 'false');
  toggle.textContent = paused ? 'Resume' : 'Pause';
});

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  if (paused) return;
  base = Math.max(16, Math.min(112, base + (Math.random() - .46) * 30));
  vals.shift();
  vals.push(Math.round(base));
  paint(true);
}, 850);

