js:
var dials = Array.prototype.slice.call(root.querySelectorAll('.mta-gauge-trio-dial'));
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = 0;

var state = dials.map(function(el, i){
  return {
    el: el,
    ring: el.querySelector('.mta-gauge-trio-ring'),
    num: el.querySelector('.mta-gauge-trio-ring b'),
    sub: el.querySelector('.mta-gauge-trio-sub'),
    cur: 0, from: 0, to: parseFloat(el.getAttribute('data-to')),
    t0: 0, delay: i * 110, dur: 1000, live: true
  };
});

function paint(s, v){
  s.cur = v;
  s.ring.style.setProperty('--p', v.toFixed(2));
  s.num.childNodes[0].nodeValue = String(Math.round(v));
  var st = v >= 85 ? 'crit' : (v >= 65 ? 'warn' : 'ok');
  s.el.setAttribute('data-state', st);
  s.sub.textContent = st === 'crit' ? 'critical' : (st === 'warn' ? 'elevated' : 'nominal');
}

function tick(ts){
  if (!root.isConnected) return;
  var busy = false;
  state.forEach(function(s){
    if (!s.live) return;
    if (!s.t0) s.t0 = ts;
    var p = Math.min(1, Math.max(0, (ts - s.t0 - s.delay) / s.dur));
    paint(s, s.from + (s.to - s.from) * (1 - Math.pow(1 - p, 3)));
    if (p < 1) busy = true; else s.live = false;
  });
  raf = busy ? requestAnimationFrame(tick) : 0;
}

function go(s, to, delay){
  s.from = s.cur; s.to = to; s.delay = delay || 0; s.t0 = 0; s.live = true;
  if (reduce){ paint(s, to); s.live = false; return; }
  if (!raf) raf = requestAnimationFrame(tick);
}

state.forEach(function(s, i){ go(s, s.to, i * 110); });

dials.forEach(function(el, i){
  el.addEventListener('click', function(){
    go(state[i], Math.round(12 + Math.random() * 86), 0);
  });
});

