js:
var list = root.querySelector('.mta-rank-flip-list');
var btn = root.querySelector('.mta-rank-flip-refresh');
var rows = Array.prototype.slice.call(list.children);
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = 0;

function val(r){ return parseFloat(r.getAttribute('data-v')); }

function paintScale(){
  var top = 0;
  rows.forEach(function(r){ top = Math.max(top, val(r)); });
  rows.forEach(function(r){
    r.querySelector('.mta-rank-flip-fill').style.width = Math.round((val(r) / top) * 100) + '%';
  });
  Array.prototype.slice.call(list.children).forEach(function(r, i){
    r.querySelector('.mta-rank-flip-pos').textContent = String(i + 1);
  });
}

function tweenNumbers(pairs){
  if (reduce){
    pairs.forEach(function(p){ p.el.textContent = Math.round(p.to).toLocaleString('en-US'); });
    return;
  }
  var t0 = 0;
  function step(ts){
    if (!root.isConnected) return;
    if (!t0) t0 = ts;
    var p = Math.min(1, (ts - t0) / 620), k = 1 - Math.pow(1 - p, 3);
    pairs.forEach(function(x){
      x.el.textContent = Math.round(x.from + (x.to - x.from) * k).toLocaleString('en-US');
    });
    raf = p < 1 ? requestAnimationFrame(step) : 0;
  }
  if (raf) cancelAnimationFrame(raf);
  raf = requestAnimationFrame(step);
}

function shuffle(){
  var first = rows.map(function(r){ return r.getBoundingClientRect().top; });
  var pairs = rows.map(function(r){
    var from = val(r);
    var to = Math.max(900, Math.round(from * (0.86 + Math.random() * 0.32)));
    r.setAttribute('data-v', String(to));
    return { el: r.querySelector('.mta-rank-flip-val'), from: from, to: to };
  });
  var order = rows.slice().sort(function(a, b){ return val(b) - val(a); });
  order.forEach(function(r){ list.appendChild(r); });
  paintScale();
  tweenNumbers(pairs);
  if (reduce) return;
  rows.forEach(function(r, i){
    var d = first[i] - r.getBoundingClientRect().top;
    r.style.transition = 'none';
    r.style.transform = 'translateY(' + d + 'px)';
  });
  void list.offsetWidth;
  rows.forEach(function(r, i){
    r.style.transition = 'transform .58s cubic-bezier(.2,.85,.25,1)';
    r.style.transitionDelay = (i * 25) + 'ms';
    r.style.transform = 'translateY(0)';
  });
}

root.classList.add('is-in');
paintScale();
btn.addEventListener('click', shuffle);

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  shuffle();
}, 3400);

