js:
var body = root.querySelector('.mta-heat-grid-body');
var totalEl = root.querySelector('.mta-heat-grid-total b');
var read = root.querySelector('.mta-heat-grid-read');
var DAYS = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
var WEEKS = 12, cells = [], counts = [];

for (var r = 0; r < DAYS.length; r++){
  var lab = document.createElement('span');
  lab.className = 'mta-heat-grid-day';
  lab.textContent = DAYS[r];
  body.appendChild(lab);
  for (var w = 0; w < WEEKS; w++){
    var weekend = r > 4 ? 0.35 : 1;
    var n = Math.round(Math.random() * 18 * weekend);
    var c = document.createElement('span');
    c.className = 'mta-heat-grid-cell';
    c.setAttribute('data-l', String(n === 0 ? 0 : Math.min(4, 1 + Math.floor(n / 5))));
    c.setAttribute('data-d', DAYS[r]);
    c.setAttribute('data-w', String(w + 1));
    c.setAttribute('data-i', String(cells.length));
    body.appendChild(c);
    cells.push(c);
    counts.push(n);
  }
}

function total(){
  var t = 0;
  counts.forEach(function(n){ t += n; });
  return t;
}

function level(n){ return n === 0 ? 0 : Math.min(4, 1 + Math.floor(n / 5)); }

totalEl.textContent = total().toLocaleString('en-US');

body.addEventListener('mouseover', function(e){
  var c = e.target.closest ? e.target.closest('.mta-heat-grid-cell') : null;
  if (!c) return;
  var i = parseInt(c.getAttribute('data-i'), 10);
  read.textContent = c.getAttribute('data-d') + ' · wk ' + c.getAttribute('data-w') + ' — ' + counts[i] + ' commits';
});
body.addEventListener('mouseleave', function(){ read.textContent = 'hover a cell'; });

cells.forEach(function(c){
  c.addEventListener('animationend', function(){ c.classList.remove('is-hit'); });
});

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  var i = Math.floor(Math.random() * cells.length);
  counts[i] = Math.min(24, counts[i] + 1 + Math.floor(Math.random() * 5));
  cells[i].setAttribute('data-l', String(level(counts[i])));
  cells[i].classList.remove('is-hit');
  void cells[i].offsetWidth;
  cells[i].classList.add('is-hit');
  totalEl.textContent = total().toLocaleString('en-US');
}, 1150);

