js:
var lines = Array.prototype.slice.call(root.querySelectorAll('.mta-diff-gutter-line[data-k]'));
var btn = root.querySelector('.mta-diff-gutter-replay');
var addEl = root.querySelector('.mta-diff-gutter-add');
var delEl = root.querySelector('.mta-diff-gutter-del');
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = 0;

var adds = lines.filter(function(l){ return l.getAttribute('data-k') === 'add'; }).length;
var dels = lines.length - adds;

lines.forEach(function(l){
  l.addEventListener('animationend', function(){ l.classList.remove('is-flash'); });
});

function counters(){
  if (reduce){
    addEl.textContent = '+' + adds;
    delEl.textContent = '−' + dels;
    return;
  }
  var t0 = 0;
  function step(ts){
    if (!root.isConnected) return;
    if (!t0) t0 = ts;
    var p = Math.min(1, (ts - t0) / 700), k = 1 - Math.pow(1 - p, 3);
    addEl.textContent = '+' + Math.round(adds * k);
    delEl.textContent = '−' + Math.round(dels * k);
    raf = p < 1 ? requestAnimationFrame(step) : 0;
  }
  if (raf) cancelAnimationFrame(raf);
  raf = requestAnimationFrame(step);
}

function play(){
  lines.forEach(function(l){ l.classList.remove('is-flash'); });
  void root.offsetWidth;
  lines.forEach(function(l){ l.classList.add('is-flash'); });
  counters();
}

btn.addEventListener('click', play);
play();

