js:
var body = root.querySelector('.mta-log-tail-body');
var jump = root.querySelector('.mta-log-tail-jump');
var pause = root.querySelector('.mta-log-tail-pause');
var filters = Array.prototype.slice.call(root.querySelectorAll('.mta-log-tail-f'));
var follow = true, paused = false, clock = 50531;

var POOL = [
  ['info', 'GET /v1/orders 200 · 34ms'],
  ['info', 'cache warm · 1,204 keys'],
  ['warn', 'retry scheduled · attempt 2/5'],
  ['info', 'POST /v1/webhooks 202 · 11ms'],
  ['error', 'upstream timeout · payments-svc'],
  ['info', 'healthcheck ok · eu-west-1'],
  ['warn', 'queue depth 812 · above soft limit'],
  ['info', 'step 4/6 · migrating schema'],
  ['info', 'GET /v1/users 200 · 8ms'],
  ['error', '5xx rate 2.1% · circuit half-open']
];

function stamp(){
  clock += 1 + Math.floor(Math.random() * 3);
  var h = Math.floor(clock / 3600) % 24, m = Math.floor(clock / 60) % 60, s = clock % 60;
  function p(n){ return (n < 10 ? '0' : '') + n; }
  return p(h) + ':' + p(m) + ':' + p(s);
}

function push(lv, msg){
  var line = document.createElement('div');
  line.className = 'mta-log-tail-line';
  line.setAttribute('data-lv', lv);
  var t = document.createElement('span');
  t.className = 'mta-log-tail-t';
  t.textContent = stamp();
  var b = document.createElement('span');
  b.className = 'mta-log-tail-lv';
  b.textContent = lv;
  var m = document.createElement('span');
  m.className = 'mta-log-tail-msg';
  m.textContent = msg;
  line.appendChild(t); line.appendChild(b); line.appendChild(m);
  body.appendChild(line);
  while (body.children.length > 60) body.removeChild(body.firstChild);
  if (follow) body.scrollTop = body.scrollHeight;
}

for (var i = 0; i < 7; i++){
  var seed = POOL[Math.floor(Math.random() * POOL.length)];
  push(seed[0], seed[1]);
}

body.addEventListener('scroll', function(){
  var far = body.scrollHeight - body.scrollTop - body.clientHeight;
  follow = far < 20;
  jump.hidden = follow;
});

jump.addEventListener('click', function(){
  follow = true;
  jump.hidden = true;
  body.scrollTop = body.scrollHeight;
  body.focus();
});

pause.addEventListener('click', function(){
  paused = !paused;
  pause.setAttribute('aria-pressed', paused ? 'true' : 'false');
  pause.textContent = paused ? 'Resume' : 'Pause';
});

filters.forEach(function(f){
  f.addEventListener('click', function(){
    filters.forEach(function(x){ x.classList.remove('is-on'); });
    f.classList.add('is-on');
    body.setAttribute('data-f', f.getAttribute('data-lv'));
    if (follow) body.scrollTop = body.scrollHeight;
  });
});

var timer = setInterval(function(){
  if (!root.isConnected){ clearInterval(timer); return; }
  if (paused) return;
  var row = POOL[Math.floor(Math.random() * POOL.length)];
  push(row[0], row[1]);
}, 900);
